package com.catchandrelease;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;

@ConfigGroup(CatchAndReleaseConfig.GROUP)
public interface CatchAndReleaseConfig extends Config
{
	String GROUP = "catchandreleasefishing";

	@ConfigItem(
		keyName = "renameDrop",
		name = "Release instead of Drop",
		description = "The inventory Drop option on matching fish is shown as Release. Clicking it still drops the fish.",
		position = 0
	)
	default boolean renameDropToRelease()
	{
		return true;
	}

	@ConfigItem(
		keyName = "leftClickRelease",
		name = "Left-click Release",
		description = "Release is the left-click option on configured fish in the inventory. The click still drops the fish.",
		position = 1
	)
	default boolean leftClickRelease()
	{
		return true;
	}

	@ConfigItem(
		keyName = "hideGroundFish",
		name = "Hide fish on the ground",
		description = "Do not draw these fish on the ground, and remove their Take, Examine, and other ground options.",
		position = 2
	)
	default boolean hideReleasedFish()
	{
		return true;
	}

	@ConfigSection(
		name = "Fish",
		description = "Which catches Release and ground hiding apply to",
		position = 3
	)
	String fishSection = "fish";

	@ConfigItem(
		keyName = "barbarian",
		name = "Barbarian fish",
		description = "Leaping trout, leaping salmon, and leaping sturgeon.",
		section = fishSection,
		position = 0
	)
	default boolean barbarianFish()
	{
		return true;
	}

	@ConfigItem(
		keyName = "flyBait",
		name = "Fly and bait fish",
		description = "Raw trout, raw salmon, raw pike, raw sardine, raw herring, raw rainbow fish, raw slimy eel, and raw cave eel.",
		section = fishSection,
		position = 1
	)
	default boolean flyBaitFish()
	{
		return true;
	}

	@ConfigItem(
		keyName = "leechfin",
		name = "Leechfin",
		description = "Leechfin, caught with a big fishing net from river spots in Vampyrium.",
		section = fishSection,
		position = 2
	)
	default boolean leechfin()
	{
		return true;
	}
}

package com.catchandrelease;

import com.google.inject.Provides;
import java.util.Set;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.ItemLayer;
import net.runelite.api.Menu;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.Renderable;
import net.runelite.api.Scene;
import net.runelite.api.TileItem;
import net.runelite.api.TileObject;
import net.runelite.api.events.MenuEntryAdded;
import net.runelite.api.events.PostMenuSort;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetUtil;
import net.runelite.client.callback.RenderCallback;
import net.runelite.client.callback.RenderCallbackManager;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.util.Text;

@PluginDescriptor(
	name = "Catch and Release Fishing",
	description = "Renames Drop to Release for barbarian, fly/bait, and leechfin, and hides those fish on the ground",
	tags = {"fishing", "barbarian", "fly", "bait", "leechfin", "drop", "release"}
)
public class CatchAndReleasePlugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private CatchAndReleaseConfig config;

	@Inject
	private RenderCallbackManager renderCallbackManager;

	private final RenderCallback renderCallback = new RenderCallback()
	{
		@Override
		public boolean addEntity(Renderable renderable, boolean drawingUi)
		{
			return shouldDrawRenderable(renderable);
		}

		@Override
		public boolean drawObject(Scene scene, TileObject object)
		{
			return shouldDrawObject(object);
		}
	};

	private volatile boolean renameEnabled = true;
	private volatile boolean leftClickEnabled = true;
	private volatile boolean hideEnabled = true;
	private volatile Set<Integer> releaseIds = ReleaseFish.enabledIds(true, true, true);

	@Provides
	CatchAndReleaseConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(CatchAndReleaseConfig.class);
	}

	@Override
	protected void startUp()
	{
		refreshConfig();
		renderCallbackManager.register(renderCallback);
	}

	@Override
	protected void shutDown()
	{
		renderCallbackManager.unregister(renderCallback);
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (CatchAndReleaseConfig.GROUP.equals(event.getGroup()))
		{
			refreshConfig();
		}
	}

	/**
	 * Remove Take, Examine, and the other ground options for these fish as the
	 * entry is added, so the hover text never offers them. Other entries on the
	 * menu stay in place.
	 */
	@Subscribe
	public void onMenuEntryAdded(MenuEntryAdded event)
	{
		if (!hideEnabled)
		{
			return;
		}
		MenuAction type = MenuAction.of(event.getType());
		if (!ReleaseFish.isGroundMenuAction(type))
		{
			return;
		}
		if (!releaseIds.contains(event.getIdentifier()))
		{
			return;
		}
		client.getMenu().removeMenuEntry(event.getMenuEntry());
	}

	/**
	 * Runs after the usual left-click swaps, which still see the option as Drop.
	 * The label changes only when Release is enabled. Left-click promotion is
	 * separate, so Drop can stay the left-click word when the rename is off.
	 */
	@Subscribe(priority = -1)
	public void onPostMenuSort(PostMenuSort event)
	{
		if (!renameEnabled && !leftClickEnabled)
		{
			return;
		}

		Menu menu = client.getMenu();
		MenuEntry[] entries = menu.getMenuEntries();
		int dropIndex = -1;
		for (int i = 0; i < entries.length; i++)
		{
			MenuEntry entry = entries[i];
			if (!isInventoryFishDrop(entry))
			{
				continue;
			}
			String shown = ReleaseFish.inventoryDropLabel(renameEnabled, Text.removeTags(entry.getOption()));
			if (!shown.equals(Text.removeTags(entry.getOption())))
			{
				entry.setOption(shown);
			}
			dropIndex = i;
		}
		if (!leftClickEnabled || dropIndex == -1)
		{
			return;
		}

		MenuEntry drop = entries[dropIndex];
		boolean typeChanged = false;
		if (drop.getType() == MenuAction.CC_OP_LOW_PRIORITY)
		{
			// Low priority ops are sorted under Use and are right-click only.
			drop.setType(MenuAction.CC_OP);
			typeChanged = true;
		}

		int top = entries.length - 1;
		if (dropIndex == top)
		{
			if (typeChanged)
			{
				menu.setMenuEntries(entries);
			}
			return;
		}

		entries[dropIndex] = entries[top];
		entries[top] = drop;
		menu.setMenuEntries(entries);
	}

	private void refreshConfig()
	{
		renameEnabled = config.renameDropToRelease();
		leftClickEnabled = config.leftClickRelease();
		hideEnabled = config.hideReleasedFish();
		releaseIds = ReleaseFish.enabledIds(config.barbarianFish(), config.flyBaitFish(), config.leechfin());
	}

	private boolean isInventoryFishDrop(MenuEntry entry)
	{
		String option = entry.getOption();
		if (option == null)
		{
			return false;
		}
		String stripped = Text.removeTags(option);
		if (!ReleaseFish.DROP_OPTION.equals(stripped) && !ReleaseFish.RELEASE_OPTION.equals(stripped))
		{
			return false;
		}
		int itemId = entry.getItemId();
		Widget widget = entry.getWidget();
		if (itemId <= 0 && widget != null)
		{
			itemId = widget.getItemId();
		}
		if (!releaseIds.contains(itemId))
		{
			return false;
		}
		int widgetId = widget != null ? widget.getId() : entry.getParam1();
		return WidgetUtil.componentToInterface(widgetId) == InterfaceID.INVENTORY;
	}

	// inspired by RuneLite's Hide Ground Items plugin.
	/**
	 * The client draws a ground pile as one object, from whichever of the three
	 * slots are filled. A brand-new pile puts its only item in {@code getTop()}
	 * and leaves bottom and middle empty, so this draw has to read all three.
	 * The README names the plugin that was read for that approach.
	 */
	private boolean shouldDrawObject(TileObject object)
	{
		if (!hideEnabled || !(object instanceof ItemLayer))
		{
			return true;
		}
		ItemLayer layer = (ItemLayer) object;
		return !ReleaseFish.pileContainsEnabledFish(
			releaseIds,
			itemId(layer.getBottom()),
			itemId(layer.getMiddle()),
			itemId(layer.getTop()));
	}

	/**
	 * Tile items that are submitted as entities, rather than as a pile, use the
	 * same id check. Inventory icons are not tile items.
	 */
	private boolean shouldDrawRenderable(Renderable renderable)
	{
		if (!hideEnabled || !(renderable instanceof TileItem))
		{
			return true;
		}
		return !releaseIds.contains(((TileItem) renderable).getId());
	}

	private static Integer itemId(Renderable renderable)
	{
		if (!(renderable instanceof TileItem))
		{
			return null;
		}
		return ((TileItem) renderable).getId();
	}
}

package com.catchandrelease;

import java.util.Collections;
import java.util.HashSet;
import java.util.Set;
import net.runelite.api.MenuAction;
import net.runelite.api.gameval.ItemID;

/**
 * Un-noted ids whose inventory Drop option is Release, and which are hidden
 * as ground items. Gameval names do not always match the name in game:
 * {@code BRUT_SPAWNING_TROUT} is leaping trout, {@code BRUT_STURGEON} is
 * leaping sturgeon, {@code HUNTING_RAW_FISH_SPECIAL} is raw rainbow fish,
 * {@code MORT_SLIMEY_EEL} is raw slimy eel, and {@code LEECHFIN} is leechfin.
 */
public final class ReleaseFish
{
	public static final String DROP_OPTION = "Drop";
	public static final String RELEASE_OPTION = "Release";

	/**
	 * Inventory label for a configured fish. Left-click promotion does not
	 * rename: with the Release toggle off, the option stays Drop.
	 */
	public static String inventoryDropLabel(boolean renameEnabled, String option)
	{
		if (renameEnabled)
		{
			return RELEASE_OPTION;
		}
		if (RELEASE_OPTION.equals(option))
		{
			return DROP_OPTION;
		}
		return option;
	}

	public static final Set<Integer> BARBARIAN_FISH = Set.of(
		ItemID.BRUT_SPAWNING_TROUT,
		ItemID.BRUT_SPAWNING_SALMON,
		ItemID.BRUT_STURGEON
	);

	public static final Set<Integer> FLY_BAIT_FISH = Set.of(
		ItemID.RAW_TROUT,
		ItemID.RAW_SALMON,
		ItemID.RAW_PIKE,
		ItemID.RAW_SARDINE,
		ItemID.RAW_HERRING,
		ItemID.HUNTING_RAW_FISH_SPECIAL,
		ItemID.MORT_SLIMEY_EEL,
		ItemID.RAW_CAVE_EEL
	);

	/**
	 * Big-net river fish. {@code LEECHFIN} is the caught item (id 33621); there
	 * is no separate raw or cooked id.
	 */
	public static final Set<Integer> LEECHFIN_FISH = Set.of(
		ItemID.LEECHFIN
	);

	private static final Set<Integer> ALL_FISH;

	static
	{
		Set<Integer> all = new HashSet<>(BARBARIAN_FISH.size() + FLY_BAIT_FISH.size() + LEECHFIN_FISH.size());
		all.addAll(BARBARIAN_FISH);
		all.addAll(FLY_BAIT_FISH);
		all.addAll(LEECHFIN_FISH);
		ALL_FISH = Collections.unmodifiableSet(all);
	}

	private ReleaseFish()
	{
	}

	/**
	 * Ids the current category toggles apply to. The returned set is immutable.
	 */
	public static Set<Integer> enabledIds(boolean barbarian, boolean flyBait, boolean leechfin)
	{
		if (barbarian && flyBait && leechfin)
		{
			return ALL_FISH;
		}
		if (!barbarian && !flyBait && !leechfin)
		{
			return Collections.emptySet();
		}
		if (barbarian && !flyBait && !leechfin)
		{
			return BARBARIAN_FISH;
		}
		if (!barbarian && flyBait && !leechfin)
		{
			return FLY_BAIT_FISH;
		}
		if (!barbarian && !flyBait)
		{
			return LEECHFIN_FISH;
		}

		Set<Integer> ids = new HashSet<>();
		if (barbarian)
		{
			ids.addAll(BARBARIAN_FISH);
		}
		if (flyBait)
		{
			ids.addAll(FLY_BAIT_FISH);
		}
		if (leechfin)
		{
			ids.addAll(LEECHFIN_FISH);
		}
		return Collections.unmodifiableSet(ids);
	}

	/**
	 * A ground pile draws at most three models: bottom, middle, and top. A new
	 * pile's only item is the top slot; the other two are null until more items
	 * are chosen. Null means that slot is empty.
	 */
	public static boolean pileContainsEnabledFish(Set<Integer> enabled, Integer bottom, Integer middle, Integer top)
	{
		return contains(enabled, bottom) || contains(enabled, middle) || contains(enabled, top);
	}

	private static boolean contains(Set<Integer> enabled, Integer itemId)
	{
		return itemId != null && enabled.contains(itemId);
	}

	/**
	 * Ground-item menu actions. Hiding one of these removes Take, Examine, and
	 * use-on-item from that fish. Walk here is not one of them.
	 */
	@SuppressWarnings("deprecation")
	public static boolean isGroundMenuAction(MenuAction action)
	{
		return action == MenuAction.GROUND_ITEM_FIRST_OPTION
			|| action == MenuAction.GROUND_ITEM_SECOND_OPTION
			|| action == MenuAction.GROUND_ITEM_THIRD_OPTION
			|| action == MenuAction.GROUND_ITEM_FOURTH_OPTION
			|| action == MenuAction.GROUND_ITEM_FIFTH_OPTION
			|| action == MenuAction.EXAMINE_ITEM_GROUND
			|| action == MenuAction.WIDGET_TARGET_ON_GROUND_ITEM
			|| action == MenuAction.ITEM_USE_ON_GROUND_ITEM;
	}
}

package com.catchandrelease;

public class CatchAndReleasePluginTest
{
	public static void main(String[] args) throws Exception
	{
		DevLaunch.launch(args);
	}
}

package com.catchandrelease;

import java.io.IOException;
import java.lang.management.ManagementFactory;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

/**
 * Dev-client entry used by the shadow jar.
 * <p>
 * Bolt's Linux launcher (including the Flatpak) execs a custom RuneLite jar as
 * {@code java -Duser.home=<bolt data> -jar <jar> -J-Duser.home=<bolt data>},
 * and adds {@code --configure} when the configure button is used. A custom
 * launch command may append more tokens, including {@code -J} / {@code -J-Xmx…}
 * JVM arguments. Those {@code -J} forms are for the official launcher. The
 * client parser rejects them ({@code J is not a recognized option}).
 * {@code -Duser.home} is already a real JVM argument on this process; Jagex
 * session ids arrive as {@code JX_SESSION_ID}, {@code JX_CHARACTER_ID}, and
 * {@code JX_DISPLAY_NAME}.
 */
final class DevLaunch
{
	static final String RELAUNCHED = "catchandrelease.relaunched";

	/**
	 * Options accepted by {@code RuneLite#main} in the client this project builds against.
	 */
	private static final Set<String> CLIENT_FLAGS = set(
		"developer-mode",
		"debug",
		"safe-mode",
		"insecure-skip-tls-verification",
		"disable-telemetry",
		"noupdate",
		"insecure-write-credentials",
		"help"
	);

	private static final Set<String> CLIENT_WITH_VALUE = set(
		"jav_config",
		"profile",
		"character",
		"sessionfile"
	);

	private static final Set<String> LAUNCHER_FLAGS = set(
		"configure",
		"postinstall",
		"nodiff"
	);

	private static final Set<String> LAUNCHER_WITH_VALUE = set(
		"scale",
		"classpath",
		"launch-mode",
		"hw-accel",
		"mode",
		"p"
	);

	private DevLaunch()
	{
	}

	@SuppressWarnings("unchecked")
	static void launch(String[] args) throws Exception
	{
		Split split = split(args);
		if (!split.ignored.isEmpty())
		{
			System.err.println("Catch and Release dev client: ignoring launcher arguments " + split.ignored);
		}

		boolean relaunched = Boolean.getBoolean(RELAUNCHED);
		List<String> currentJvm = ManagementFactory.getRuntimeMXBean().getInputArguments();
		if (!relaunched && needsRelaunch(assertionsEnabled(), currentJvm, split.jvmArgs))
		{
			System.err.println("Catch and Release dev client: relaunching with assertions enabled");
			int code = relaunch(split, currentJvm);
			System.exit(code);
		}
		if (!assertionsEnabled())
		{
			throw new IllegalStateException("Assertions are not enabled. Relaunch with -ea failed.");
		}

		ExternalPluginManager.loadBuiltin(CatchAndReleasePlugin.class);
		RuneLite.main(split.clientArgs.toArray(new String[0]));
	}

	static boolean assertionsEnabled()
	{
		boolean enabled = false;
		assert enabled = true;
		return enabled;
	}

	/**
	 * @param requestedJvmArgs JVM arguments extracted from {@code -J} and other launcher options
	 */
	static boolean needsRelaunch(boolean assertionsEnabled, List<String> currentJvmArgs, List<String> requestedJvmArgs)
	{
		if (!assertionsEnabled)
		{
			return true;
		}
		for (String requested : requestedJvmArgs)
		{
			if (isEnableAssertions(requested) || currentJvmArgs.contains(requested))
			{
				continue;
			}
			return true;
		}
		return false;
	}

	static Split split(String[] args)
	{
		List<String> jvmArgs = new ArrayList<>();
		List<String> clientArgs = new ArrayList<>();
		List<String> ignored = new ArrayList<>();
		if (args == null)
		{
			return new Split(jvmArgs, clientArgs, ignored);
		}

		for (int i = 0; i < args.length; i++)
		{
			String arg = args[i];
			if (arg == null || arg.isEmpty())
			{
				continue;
			}
			if ("--".equals(arg))
			{
				clientArgs.add(arg);
				clientArgs.addAll(Arrays.asList(args).subList(i + 1, args.length));
				break;
			}

			String jvm = jvmArgument(arg);
			if (jvm != null)
			{
				ignored.add(arg);
				if (jvm.isEmpty())
				{
					if (i + 1 < args.length)
					{
						jvmArgs.add(args[++i]);
					}
				}
				else if (!isDisableAssertions(jvm))
				{
					jvmArgs.add(jvm);
				}
				continue;
			}

			String name = longName(arg);
			if (name != null && (CLIENT_FLAGS.contains(name) || CLIENT_WITH_VALUE.contains(name)))
			{
				clientArgs.add(arg);
				if (CLIENT_WITH_VALUE.contains(name) && !arg.contains("=") && i + 1 < args.length)
				{
					clientArgs.add(args[++i]);
				}
				continue;
			}

			if (name != null && (LAUNCHER_FLAGS.contains(name) || LAUNCHER_WITH_VALUE.contains(name)))
			{
				ignored.add(arg);
				String attached = attachedValue(arg);
				if ("scale".equals(name))
				{
					String scale = attached;
					if (scale == null && i + 1 < args.length)
					{
						scale = args[++i];
						ignored.add(scale);
					}
					if (scale != null && !scale.isEmpty())
					{
						jvmArgs.add("-Dsun.java2d.dpiaware=true");
						jvmArgs.add("-Dsun.java2d.uiScale=" + scale);
					}
				}
				else if (LAUNCHER_WITH_VALUE.contains(name) && attached == null && i + 1 < args.length && !args[i + 1].startsWith("-"))
				{
					ignored.add(args[++i]);
				}
				continue;
			}

			if (arg.startsWith("-"))
			{
				ignored.add(arg);
				continue;
			}
			clientArgs.add(arg);
		}
		return new Split(jvmArgs, clientArgs, ignored);
	}

	static List<String> command(
		String javaBin,
		List<String> currentJvmArgs,
		List<String> requestedJvmArgs,
		String classpath,
		String mainClass,
		List<String> clientArgs)
	{
		List<String> cmd = new ArrayList<>();
		cmd.add(javaBin);
		if (currentJvmArgs != null)
		{
			for (String arg : currentJvmArgs)
			{
				if (arg == null || isEnableAssertions(arg) || isDisableAssertions(arg))
				{
					continue;
				}
				cmd.add(arg);
			}
		}
		if (requestedJvmArgs != null)
		{
			for (String arg : requestedJvmArgs)
			{
				if (arg == null || arg.isEmpty() || isDisableAssertions(arg) || isEnableAssertions(arg) || cmd.contains(arg))
				{
					continue;
				}
				cmd.add(arg);
			}
		}
		cmd.add("-ea");
		String relaunchProp = "-D" + RELAUNCHED + "=true";
		if (!cmd.contains(relaunchProp))
		{
			cmd.add(relaunchProp);
		}
		cmd.add("-cp");
		cmd.add(classpath);
		cmd.add(mainClass);
		if (clientArgs != null)
		{
			cmd.addAll(clientArgs);
		}
		return cmd;
	}

	private static int relaunch(Split split, List<String> currentJvm) throws IOException, InterruptedException
	{
		List<String> cmd = command(
			javaBinary().toString(),
			currentJvm,
			split.jvmArgs,
			System.getProperty("java.class.path"),
			CatchAndReleasePluginTest.class.getName(),
			split.clientArgs);
		Process process = new ProcessBuilder(cmd).inheritIO().start();
		return process.waitFor();
	}

	private static Path javaBinary()
	{
		String os = System.getProperty("os.name", "");
		String exe = os.toLowerCase(Locale.ENGLISH).contains("win") ? "java.exe" : "java";
		Path bin = Paths.get(System.getProperty("java.home"), "bin", exe);
		if (Files.isRegularFile(bin))
		{
			return bin;
		}
		return Paths.get(exe);
	}

	/**
	 * @return the JVM argument to apply, empty when the next token is that argument, or null
	 */
	private static String jvmArgument(String arg)
	{
		if ("-J".equals(arg) || "--J".equals(arg))
		{
			return "";
		}
		if (arg.startsWith("--J="))
		{
			return arg.substring(4);
		}
		if (arg.startsWith("--J") && arg.length() > 3)
		{
			return arg.substring(3);
		}
		if (arg.startsWith("-J") && arg.length() > 2)
		{
			return arg.substring(2);
		}
		if (arg.startsWith("-D") || arg.startsWith("-X") || arg.startsWith("-javaagent:") || arg.startsWith("--add-")
			|| arg.startsWith("--enable-native-access") || arg.startsWith("--enable-preview"))
		{
			return arg;
		}
		if (isEnableAssertions(arg) || isDisableAssertions(arg))
		{
			return arg;
		}
		return null;
	}

	private static boolean isEnableAssertions(String arg)
	{
		return "-ea".equals(arg) || "-enableassertions".equals(arg) || "-esa".equals(arg)
			|| arg.startsWith("-ea:") || arg.startsWith("-enableassertions:");
	}

	private static boolean isDisableAssertions(String arg)
	{
		return "-da".equals(arg) || "-disableassertions".equals(arg) || "-dsa".equals(arg)
			|| arg.startsWith("-da:") || arg.startsWith("-disableassertions:");
	}

	private static String longName(String arg)
	{
		if (!arg.startsWith("--") || arg.length() < 3)
		{
			return null;
		}
		String body = arg.substring(2);
		int eq = body.indexOf('=');
		return eq >= 0 ? body.substring(0, eq) : body;
	}

	private static String attachedValue(String arg)
	{
		int eq = arg.indexOf('=');
		if (arg.startsWith("--") && eq > 2)
		{
			return arg.substring(eq + 1);
		}
		return null;
	}

	private static Set<String> set(String... values)
	{
		return Collections.unmodifiableSet(new HashSet<>(Arrays.asList(values)));
	}

	static final class Split
	{
		final List<String> jvmArgs;
		final List<String> clientArgs;
		final List<String> ignored;

		Split(List<String> jvmArgs, List<String> clientArgs, List<String> ignored)
		{
			this.jvmArgs = jvmArgs;
			this.clientArgs = clientArgs;
			this.ignored = ignored;
		}
	}
}

package com.catchandrelease;

import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import org.junit.Assert;
import org.junit.Test;

public class DevLaunchTest
{
	@Test
	public void boltCustomJarArgsAreJvmPropertiesNotClientOptions()
	{
		DevLaunch.Split split = DevLaunch.split(new String[]{
			"-J-Duser.home=/home/user/.var/app/com.adamcake.Bolt/data/bolt-launcher"
		});

		Assert.assertEquals(
			Collections.singletonList("-Duser.home=/home/user/.var/app/com.adamcake.Bolt/data/bolt-launcher"),
			split.jvmArgs);
		Assert.assertTrue(split.clientArgs.isEmpty());
	}

	@Test
	public void configureAndSeparateJvmArgsAreStripped()
	{
		DevLaunch.Split split = DevLaunch.split(new String[]{
			"-J-Duser.home=/bolt",
			"--configure",
			"-J",
			"-Dsun.java2d.uiScale=2",
			"--developer-mode",
			"--debug"
		});

		Assert.assertEquals(Arrays.asList(
			"-Duser.home=/bolt",
			"-Dsun.java2d.uiScale=2"
		), split.jvmArgs);
		Assert.assertEquals(Arrays.asList("--developer-mode", "--debug"), split.clientArgs);
		Assert.assertFalse(split.ignored.contains("--developer-mode"));
		Assert.assertTrue(split.ignored.contains("--configure"));
	}

	@Test
	public void clientOptionsWithValuesAreKept()
	{
		DevLaunch.Split split = DevLaunch.split(new String[]{
			"--profile",
			"leagues",
			"--character=Fish",
			"--sessionfile",
			"/tmp/session",
			"--jav_config=https://example.invalid/jav_config.ws",
			"--safe-mode",
			"--insecure-write-credentials"
		});

		Assert.assertEquals(Arrays.asList(
			"--profile",
			"leagues",
			"--character=Fish",
			"--sessionfile",
			"/tmp/session",
			"--jav_config=https://example.invalid/jav_config.ws",
			"--safe-mode",
			"--insecure-write-credentials"
		), split.clientArgs);
		Assert.assertTrue(split.jvmArgs.isEmpty());
	}

	@Test
	public void launcherOnlyOptionsDoNotReachTheClient()
	{
		DevLaunch.Split split = DevLaunch.split(new String[]{
			"--scale=1.5",
			"--classpath",
			"client.jar",
			"--launch-mode",
			"JVM",
			"--hw-accel",
			"OPENGL",
			"--mode=OFF",
			"--postinstall",
			"--nodiff",
			"-psn_0_352342",
			"--not-a-runelite-option",
			"--developer-mode"
		});

		Assert.assertEquals(Collections.singletonList("--developer-mode"), split.clientArgs);
		Assert.assertEquals(Arrays.asList(
			"-Dsun.java2d.dpiaware=true",
			"-Dsun.java2d.uiScale=1.5"
		), split.jvmArgs);
		Assert.assertFalse(split.clientArgs.contains("client.jar"));
		Assert.assertFalse(split.clientArgs.contains("JVM"));
		Assert.assertFalse(split.clientArgs.contains("--configure"));
	}

	@Test
	public void rawJvmArgsAndAssertionFlagsAreNotClientOptions()
	{
		DevLaunch.Split split = DevLaunch.split(new String[]{
			"-Xmx512m",
			"-ea",
			"-da",
			"--J=-Dfoo=bar",
			"--",
			"--configure"
		});

		Assert.assertEquals(Arrays.asList("-Xmx512m", "-ea", "-Dfoo=bar"), split.jvmArgs);
		Assert.assertEquals(Arrays.asList("--", "--configure"), split.clientArgs);
		Assert.assertFalse(split.jvmArgs.contains("-da"));
	}

	@Test
	public void relaunchCarriesDeveloperModeAssertionsAndBoltHome()
	{
		List<String> cmd = DevLaunch.command(
			"/usr/bin/java",
			Collections.singletonList("-Duser.home=/bolt"),
			Arrays.asList("-Duser.home=/bolt", "-Dsun.java2d.uiScale=2"),
			"/tmp/catch-and-release-all.jar",
			"com.catchandrelease.CatchAndReleasePluginTest",
			Arrays.asList("--developer-mode", "--debug"));

		Assert.assertEquals("/usr/bin/java", cmd.get(0));
		Assert.assertTrue(cmd.contains("-ea"));
		Assert.assertTrue(cmd.contains("-Duser.home=/bolt"));
		Assert.assertTrue(cmd.contains("-Dsun.java2d.uiScale=2"));
		Assert.assertTrue(cmd.contains("-D" + DevLaunch.RELAUNCHED + "=true"));
		Assert.assertEquals(Arrays.asList(
			"-cp",
			"/tmp/catch-and-release-all.jar",
			"com.catchandrelease.CatchAndReleasePluginTest",
			"--developer-mode",
			"--debug"
		), cmd.subList(cmd.indexOf("-cp"), cmd.size()));
		Assert.assertEquals(1, count(cmd, "-Duser.home=/bolt"));
		Assert.assertFalse(cmd.contains("-J-Duser.home=/bolt"));
	}

	@Test
	public void relaunchIsSkippedWhenAssertionsAndJvmArgsAreAlreadyApplied()
	{
		Assert.assertTrue(DevLaunch.needsRelaunch(
			false,
			Collections.singletonList("-Duser.home=/bolt"),
			Collections.singletonList("-Duser.home=/bolt")));
		Assert.assertFalse(DevLaunch.needsRelaunch(
			true,
			Arrays.asList("-ea", "-Duser.home=/bolt"),
			Collections.singletonList("-Duser.home=/bolt")));
		Assert.assertTrue(DevLaunch.needsRelaunch(
			true,
			Collections.singletonList("-ea"),
			Collections.singletonList("-Dsun.java2d.uiScale=2")));
		Assert.assertFalse(DevLaunch.needsRelaunch(
			true,
			Collections.singletonList("-ea"),
			Collections.<String>emptyList()));
	}

	private static int count(List<String> values, String target)
	{
		int n = 0;
		for (String value : values)
		{
			if (target.equals(value))
			{
				n++;
			}
		}
		return n;
	}
}

package com.catchandrelease;

import java.util.Arrays;
import java.util.Collections;
import java.util.Set;
import net.runelite.api.MenuAction;
import net.runelite.api.gameval.ItemID;
import org.junit.Assert;
import org.junit.Test;

public class ReleaseFishTest
{
	@Test
	public void barbarianCatchesUseBrutItemIds()
	{
		Assert.assertTrue(ReleaseFish.BARBARIAN_FISH.contains(ItemID.BRUT_SPAWNING_TROUT));
		Assert.assertTrue(ReleaseFish.BARBARIAN_FISH.contains(ItemID.BRUT_SPAWNING_SALMON));
		Assert.assertTrue(ReleaseFish.BARBARIAN_FISH.contains(ItemID.BRUT_STURGEON));
	}

	@Test
	public void flyAndBaitCatchesUseRawItemIds()
	{
		Assert.assertTrue(ReleaseFish.FLY_BAIT_FISH.contains(ItemID.RAW_TROUT));
		Assert.assertTrue(ReleaseFish.FLY_BAIT_FISH.contains(ItemID.RAW_SALMON));
		Assert.assertTrue(ReleaseFish.FLY_BAIT_FISH.contains(ItemID.RAW_PIKE));
		Assert.assertTrue(ReleaseFish.FLY_BAIT_FISH.contains(ItemID.RAW_SARDINE));
		Assert.assertTrue(ReleaseFish.FLY_BAIT_FISH.contains(ItemID.RAW_HERRING));
		Assert.assertTrue(ReleaseFish.FLY_BAIT_FISH.contains(ItemID.HUNTING_RAW_FISH_SPECIAL));
		Assert.assertTrue(ReleaseFish.FLY_BAIT_FISH.contains(ItemID.MORT_SLIMEY_EEL));
		Assert.assertTrue(ReleaseFish.FLY_BAIT_FISH.contains(ItemID.RAW_CAVE_EEL));
	}

	@Test
	public void leechfinUsesTheGamevalItemId()
	{
		Assert.assertTrue(ReleaseFish.LEECHFIN_FISH.contains(ItemID.LEECHFIN));
		Assert.assertEquals(33621, ItemID.LEECHFIN);
		Assert.assertFalse(ReleaseFish.LEECHFIN_FISH.contains(ItemID.BLOOD_SAC));
	}

	@Test
	public void cookedRoeShrimpAndBurntFishAreNotReleasable()
	{
		Assert.assertTrue(Collections.disjoint(
			ReleaseFish.enabledIds(true, true, true),
			Arrays.asList(
				ItemID.TROUT,
				ItemID.SALMON,
				ItemID.PIKE,
				ItemID.SARDINE,
				ItemID.HERRING,
				ItemID.HUNTING_FISH_SPECIAL,
				ItemID.HUNTING_RAW_FISH_SPECIAL_BURNT,
				ItemID.MORT_SLIMEY_EEL_COOKED,
				ItemID.CAVE_EEL,
				ItemID.BURNT_CAVE_EEL,
				ItemID.BRUT_ROE,
				ItemID.BRUT_CAVIAR,
				ItemID.RAW_SHRIMP,
				ItemID.SHRIMP,
				ItemID.RAW_LOBSTER,
				ItemID.BRUT_FISHING_ROD,
				ItemID.COINS,
				ItemID.BLOOD_SAC
			)));
	}

	@Test
	public void categoriesDoNotOverlap()
	{
		Assert.assertTrue(Collections.disjoint(ReleaseFish.BARBARIAN_FISH, ReleaseFish.FLY_BAIT_FISH));
		Assert.assertTrue(Collections.disjoint(ReleaseFish.BARBARIAN_FISH, ReleaseFish.LEECHFIN_FISH));
		Assert.assertTrue(Collections.disjoint(ReleaseFish.FLY_BAIT_FISH, ReleaseFish.LEECHFIN_FISH));
	}

	@Test
	public void enabledIdsFollowTheCategoryToggles()
	{
		Set<Integer> all = ReleaseFish.enabledIds(true, true, true);
		Set<Integer> barbarian = ReleaseFish.enabledIds(true, false, false);
		Set<Integer> flyBait = ReleaseFish.enabledIds(false, true, false);
		Set<Integer> leechfin = ReleaseFish.enabledIds(false, false, true);
		Set<Integer> none = ReleaseFish.enabledIds(false, false, false);

		Assert.assertTrue(all.contains(ItemID.RAW_TROUT));
		Assert.assertTrue(all.contains(ItemID.BRUT_STURGEON));
		Assert.assertTrue(all.contains(ItemID.MORT_SLIMEY_EEL));
		Assert.assertTrue(all.contains(ItemID.RAW_CAVE_EEL));
		Assert.assertTrue(all.contains(ItemID.LEECHFIN));

		Assert.assertTrue(flyBait.contains(ItemID.RAW_TROUT));
		Assert.assertFalse(flyBait.contains(ItemID.BRUT_SPAWNING_TROUT));
		Assert.assertFalse(flyBait.contains(ItemID.LEECHFIN));
		Assert.assertTrue(barbarian.contains(ItemID.BRUT_SPAWNING_SALMON));
		Assert.assertFalse(barbarian.contains(ItemID.RAW_TROUT));
		Assert.assertFalse(barbarian.contains(ItemID.RAW_CAVE_EEL));
		Assert.assertFalse(barbarian.contains(ItemID.LEECHFIN));
		Assert.assertTrue(leechfin.contains(ItemID.LEECHFIN));
		Assert.assertFalse(leechfin.contains(ItemID.RAW_TROUT));
		Assert.assertFalse(leechfin.contains(ItemID.BRUT_STURGEON));

		Assert.assertTrue(none.isEmpty());
		Assert.assertTrue(Collections.disjoint(none, all));
	}

	@Test
	public void onlyDropOnAnEnabledFishIsRelease()
	{
		Set<Integer> ids = ReleaseFish.enabledIds(true, true, true);
		Assert.assertTrue(isRelease(ReleaseFish.DROP_OPTION, ItemID.RAW_TROUT, ids));
		Assert.assertTrue(isRelease(ReleaseFish.DROP_OPTION, ItemID.BRUT_SPAWNING_SALMON, ids));
		Assert.assertTrue(isRelease(ReleaseFish.DROP_OPTION, ItemID.RAW_CAVE_EEL, ReleaseFish.enabledIds(false, true, false)));
		Assert.assertTrue(isRelease(ReleaseFish.DROP_OPTION, ItemID.LEECHFIN, ReleaseFish.enabledIds(false, false, true)));

		Assert.assertFalse(isRelease("Use", ItemID.RAW_SALMON, ids));
		Assert.assertFalse(isRelease(ReleaseFish.DROP_OPTION, ItemID.TROUT, ids));
		Assert.assertFalse(isRelease(ReleaseFish.DROP_OPTION, ItemID.RAW_TROUT, ReleaseFish.enabledIds(true, false, false)));
		Assert.assertFalse(isRelease(ReleaseFish.DROP_OPTION, ItemID.BRUT_STURGEON, ReleaseFish.enabledIds(false, true, false)));
		Assert.assertFalse(isRelease(ReleaseFish.DROP_OPTION, ItemID.LEECHFIN, ReleaseFish.enabledIds(true, true, false)));
		Assert.assertFalse(isRelease(null, ItemID.RAW_TROUT, ids));
	}

	@Test
	public void aNewPileWithOnlyTheTopSlotFilledIsHidden()
	{
		Set<Integer> ids = ReleaseFish.enabledIds(true, true, true);
		Assert.assertTrue(ReleaseFish.pileContainsEnabledFish(ids, null, null, ItemID.RAW_TROUT));
		Assert.assertTrue(ReleaseFish.pileContainsEnabledFish(ids, null, null, ItemID.LEECHFIN));
		Assert.assertTrue(ReleaseFish.pileContainsEnabledFish(ids, ItemID.BRUT_STURGEON, null, null));
		Assert.assertTrue(ReleaseFish.pileContainsEnabledFish(ids, null, ItemID.RAW_SALMON, ItemID.COINS));

		Assert.assertFalse(ReleaseFish.pileContainsEnabledFish(ids, null, null, null));
		Assert.assertFalse(ReleaseFish.pileContainsEnabledFish(ids, ItemID.COINS, ItemID.TROUT, ItemID.BLOOD_SAC));
		Assert.assertFalse(ReleaseFish.pileContainsEnabledFish(ReleaseFish.enabledIds(false, false, false), null, null, ItemID.RAW_TROUT));
		Assert.assertFalse(ReleaseFish.pileContainsEnabledFish(ReleaseFish.enabledIds(true, true, false), null, null, ItemID.LEECHFIN));
	}

	@Test
	public void leftClickDoesNotRenameWhenReleaseToggleIsOff()
	{
		Assert.assertEquals(ReleaseFish.DROP_OPTION, ReleaseFish.inventoryDropLabel(false, ReleaseFish.DROP_OPTION));
		Assert.assertEquals(ReleaseFish.DROP_OPTION, ReleaseFish.inventoryDropLabel(false, ReleaseFish.RELEASE_OPTION));
		Assert.assertEquals(ReleaseFish.RELEASE_OPTION, ReleaseFish.inventoryDropLabel(true, ReleaseFish.DROP_OPTION));
		Assert.assertEquals(ReleaseFish.RELEASE_OPTION, ReleaseFish.inventoryDropLabel(true, ReleaseFish.RELEASE_OPTION));
		Assert.assertEquals("Use", ReleaseFish.inventoryDropLabel(false, "Use"));
	}

	private static boolean isRelease(String option, int itemId, Set<Integer> enabledIds)
	{
		return ReleaseFish.DROP_OPTION.equals(option) && enabledIds.contains(itemId);
	}

	@Test
	public void groundMenusForTheseFishAreTheOnesThatGetHidden()
	{
		Assert.assertTrue(ReleaseFish.isGroundMenuAction(MenuAction.GROUND_ITEM_FIRST_OPTION));
		Assert.assertTrue(ReleaseFish.isGroundMenuAction(MenuAction.GROUND_ITEM_FIFTH_OPTION));
		Assert.assertTrue(ReleaseFish.isGroundMenuAction(MenuAction.EXAMINE_ITEM_GROUND));
		Assert.assertTrue(ReleaseFish.isGroundMenuAction(MenuAction.WIDGET_TARGET_ON_GROUND_ITEM));
		Assert.assertFalse(ReleaseFish.isGroundMenuAction(MenuAction.WALK));
		Assert.assertFalse(ReleaseFish.isGroundMenuAction(MenuAction.CC_OP));
		Assert.assertFalse(ReleaseFish.isGroundMenuAction(MenuAction.EXAMINE_NPC));
		Assert.assertFalse(ReleaseFish.isGroundMenuAction(MenuAction.CANCEL));
	}
